  function deviceSourceLabel(device){return `${device.name} · ${device.name==='HELOWIN WATCH H1'?'IMEI':'SN'} ${device.id}`;}
  function sourceType(source){return String(source||'').split(' · ')[0];}
  function displaySourceName(source){return sourceType(source);}
  function normalizeLegacyWatchSource(raw){
    const rename=name=>name==='WATCH H1'?'HELOWIN WATCH H1':name;
    if(Array.isArray(raw.priority))raw.priority=raw.priority.map(rename);
    if(Array.isArray(raw.boundDevices))raw.boundDevices=raw.boundDevices.map(rename);
    for(const route of Object.keys(raw.priorities||{}))if(Array.isArray(raw.priorities[route]))raw.priorities[route]=raw.priorities[route].map(rename);
    for(const policy of Object.values(raw.policies||{}))if(policy?.source)policy.source=rename(policy.source);
  }
  function loadSourceSettings(){
    let raw={};
    try{raw=JSON.parse(localStorage.getItem('heartplus.sourceSettings.v3')||localStorage.getItem('heartplus.sourceSettings.v2')||'{}');}catch{}
    normalizeLegacyWatchSource(raw);
    const storedDevices=Array.isArray(raw.boundDevices)?raw.boundDevices.filter(name=>deviceDefinitions[name]):['24小时心电贴','HELOWIN WATCH H1','心电卡片'];
    const legacyDevices=!raw.deviceCatalogVersion&&storedDevices.includes('心电卡片')?[...new Set(['24小时心电贴','HELOWIN WATCH H1',...storedDevices])]:storedDevices;
    const deviceInstances=Array.isArray(raw.deviceInstances)
      ?raw.deviceInstances.filter(item=>item&&deviceDefinitions[item.name]&&item.id).map(item=>({name:item.name,id:String(item.id),bound:item.bound!==false,history:item.history!==false}))
      :legacyDevices.map(name=>({name,id:defaultDeviceIds[name],bound:true,history:true}));
    if(!raw.sourceStatusExamplesVersion&&!deviceInstances.some(item=>!item.bound)){
      let id=864202600017899;
      while(deviceInstances.some(item=>item.name==='HELOWIN WATCH H1'&&item.id===String(id)))id++;
      deviceInstances.push({name:'HELOWIN WATCH H1',id:String(id),bound:false,history:true});
    }
    const boundDevices=[...new Set(deviceInstances.filter(item=>item.bound).map(item=>item.name))];
    const authorized={'苹果健康':raw.authorized?.['苹果健康']!==false,'华为运动健康':raw.authorized?.['华为运动健康']!==false};
    const historicalPlatforms={'苹果健康':raw.historicalPlatforms?.['苹果健康']!==false,'华为运动健康':raw.historicalPlatforms?.['华为运动健康']!==false};
    const legacyPriority=Array.isArray(raw.priority)?raw.priority:defaultPriority,oldHeartDefault=['苹果健康','华为运动健康','心电卡片'],priorities={};
    for(const route of priorityRoutes){
      const isHeartMetric=route==='heart'||route==='hrv';
      const catalog=isHeartMetric?sourceOptions[route].flatMap(name=>platformNames.includes(name)?authorized[name]||historicalPlatforms[name]?[name]:[]:deviceInstances.filter(item=>item.name===name&&(item.bound||item.history)).map(deviceSourceLabel)):[...new Set([...(sourceOptions[route]||[]),...Object.entries(deviceDefinitions).filter(([,routes])=>routes.includes(route)).map(([name])=>name)])];
      const saved=raw.priorities?.[route],legacySource=raw.policies?.[route]?.mode==='specified'?raw.policies[route].source:null;
      const oldDefault=isHeartMetric&&Array.isArray(saved)&&saved.length===oldHeartDefault.length&&saved.every((name,index)=>name===oldHeartDefault[index]);
      const base=oldDefault&&!raw.deviceCatalogVersion?defaultPriority:Array.isArray(saved)?saved:legacySource?[legacySource,...legacyPriority]:legacyPriority;
      const expanded=base.flatMap(name=>isHeartMetric&&deviceDefinitions[name]?deviceInstances.filter(item=>item.name===name&&(item.bound||item.history)).map(deviceSourceLabel):[name]);
      priorities[route]=[...new Set([...expanded.filter(name=>catalog.includes(name)),...catalog])];
      if(isHeartMetric&&!Array.isArray(saved)){const active=priorities[route].filter(name=>!deviceInstances.some(item=>deviceSourceLabel(item)===name&&!item.bound)),unbound=priorities[route].filter(name=>deviceInstances.some(item=>deviceSourceLabel(item)===name&&!item.bound));priorities[route]=[...active,...unbound];}
    }
    return {deviceCatalogVersion:3,sourceStatusExamplesVersion:1,authorized,historicalPlatforms,boundDevices,deviceInstances,priorities};
  }
  const state = { route:'home', ranges:{},periodOffsets:{},activityDateOffset:0,recordLimits:{},expandedRecordGroups:new Set(),temp:'wrist',sleepSource:'apple',hrvMetric:null,hrvMetricSource:null,heartAssessmentMetric:'tension',demoStatus:'normal',stack:[],added:{weight:[],diet:[],bp:[]},latestWeight:null,latestBp:null,extraDiet:0,sourceSheetRoute:null,sourceSettings:loadSourceSettings(),dragPriority:null };

  function icon(name, cls='') { return `<svg class="${cls}" viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.info}</svg>`; }
  function e(s){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));}
  function attr(obj){return encodeURIComponent(JSON.stringify(obj));}
  function saveSourceSettings(){try{localStorage.setItem('heartplus.sourceSettings.v3',JSON.stringify(state.sourceSettings));}catch{}}
  saveSourceSettings();
  function policyRoute(route){return activityDetails.has(route)?'activity':route;}
  function eligibleSources(route){route=policyRoute(route);if(route==='heart'||route==='hrv')return sourceOptions[route].flatMap(name=>platformNames.includes(name)?state.sourceSettings.authorized[name]||state.sourceSettings.historicalPlatforms[name]?[name]:[]:state.sourceSettings.deviceInstances.filter(item=>item.name===name&&(item.bound||item.history)).map(deviceSourceLabel));const possible=[...(sourceOptions[route]||[]),...Object.entries(deviceDefinitions).filter(([name,routes])=>routes.includes(route)&&!sourceOptions[route]?.includes(name)).map(([name])=>name)];return possible.filter(name=>platformNames.includes(name)?state.sourceSettings.authorized[name]:name==='手动录入'||state.sourceSettings.boundDevices.includes(name));}
  function orderedSources(route){route=policyRoute(route);const available=eligibleSources(route),order=state.sourceSettings.priorities[route]||defaultPriority;return [...available].sort((a,b)=>order.indexOf(a)-order.indexOf(b));}
  function selectedSource(route=state.route){if(!sourceOptions[route])return '';if(aggregateRoutes.has(route))return eligibleSources(route).length?'全部来源':'';return orderedSources(route)[0]||'';}
  function appendPrioritySource(route,name){const order=state.sourceSettings.priorities[route];if(!order||order.includes(name))return;let position=order.length;if(route==='heart'||route==='hrv')while(position>0&&state.sourceSettings.deviceInstances.some(item=>!item.bound&&deviceSourceLabel(item)===order[position-1]))position--;order.splice(position,0,name);}
  function reorderPriority(route,name,targetName){route=policyRoute(route);const list=state.sourceSettings.priorities[route];if(!list)return;const from=list.indexOf(name),to=list.indexOf(targetName);if(from<0||to<0||from===to)return;list.splice(from,1);list.splice(list.indexOf(targetName)+(from<to?1:0),0,name);saveSourceSettings();render(false);renderSourcePicker();}
  function startPriorityDrag(event){const handle=event.target.closest('[data-priority-drag]');if(!handle||!state.sourceSheetRoute||aggregateRoutes.has(state.sourceSheetRoute))return;const row=handle.closest('.priority-row');state.dragPriority={route:state.sourceSheetRoute,name:handle.dataset.priorityDrag,row,startY:event.clientY,target:null};row?.classList.add('dragging');handle.setPointerCapture?.(event.pointerId);event.preventDefault();}
  function priorityDropTarget(event,drag){const rows=[...(document.querySelectorAll?.('.priority-row')||[])];const row=rows.find(item=>{if(item===drag.row)return false;const box=item.getBoundingClientRect();return event.clientY>=box.top&&event.clientY<=box.bottom;});return row||document.elementFromPoint(event.clientX,event.clientY)?.closest('.priority-row');}
  function movePriorityDrag(event){const drag=state.dragPriority;if(!drag)return;drag.row.style.transform=`translateY(${event.clientY-drag.startY}px)`;drag.target?.classList.remove('drop-target');const target=priorityDropTarget(event,drag);drag.target=target&&target.dataset.priorityName!==drag.name?target:null;drag.target?.classList.add('drop-target');event.preventDefault();}
  function endPriorityDrag(event){const drag=state.dragPriority;if(!drag)return;const target=priorityDropTarget(event,drag)||drag.target;drag.row?.classList.remove('dragging');drag.row.style.transform='';drag.target?.classList.remove('drop-target');state.dragPriority=null;if(target?.dataset.priorityName&&target.dataset.priorityName!==drag.name)reorderPriority(drag.route,drag.name,target.dataset.priorityName);}
  function setPlatformAuthorization(name,authorized){if(!platformNames.includes(name))return;state.sourceSettings.authorized[name]=authorized;if(authorized){state.sourceSettings.historicalPlatforms[name]=true;for(const route of ['heart','hrv'])appendPrioritySource(route,name);}saveSourceSettings();closeSheet();render(false);}
  function setDeviceBound(id,bound){const item=state.sourceSettings.deviceInstances.find(device=>device.id===id);if(!item)return;item.bound=bound;if(!bound)item.history=true;state.sourceSettings.boundDevices=[...new Set(state.sourceSettings.deviceInstances.filter(device=>device.bound).map(device=>device.name))];if(!bound){const label=deviceSourceLabel(item);for(const route of deviceDefinitions[item.name]||[]){const order=state.sourceSettings.priorities[route];if(!order)continue;const index=order.indexOf(label);if(index>=0){order.splice(index,1);order.push(label);}}}saveSourceSettings();closeSheet();render(false);}
  function emptyRecords(){return '<div class="surface module-empty">--</div>';}
  function blankChart(title,opts={}){const labels=opts.labels||mockLabels(currentRange());return chartCard(title,chart(Array(labels.length).fill(null),{kind:opts.kind||'scatter',labels,min:opts.min??0,max:opts.max??100,unit:opts.unit||'',color:opts.color||C.blue,aria:title,source:selectedSource(),referenceRanges:opts.referenceRanges||opts.referenceRange}));}
  function currentRange(){return state.ranges[state.route] || ({activity:'week',temperature:'week',weight:'month',diet:'day',sleep:'day'}[state.route]||'day');}
  function setRange(range){state.ranges[state.route]=range;render(false);}
  function periodOffset(route=state.route,range=currentRange()){return state.periodOffsets[route]?.[range]||0;}
  function setPeriodStep(step){const route=state.route,range=currentRange(),next=Math.min(0,periodOffset(route,range)+step);state.periodOffsets[route]??={};state.periodOffsets[route][range]=next;render(false);}
  function resetPeriod(){const route=state.route,range=currentRange();state.periodOffsets[route]??={};state.periodOffsets[route][range]=0;render(false);}
  function periodBounds(range=currentRange(),route=state.route){const now=new Date(),offset=periodOffset(route,range),start=new Date(now.getFullYear(),now.getMonth(),now.getDate()),end=new Date(start);if(range==='day'){start.setDate(start.getDate()+offset);end.setDate(start.getDate()+1);}else if(range==='week'){start.setDate(start.getDate()-((start.getDay()+6)%7)+offset*7);end.setTime(start.getTime());end.setDate(end.getDate()+7);}else if(range==='month'){start.setDate(1);start.setMonth(start.getMonth()+offset);end.setTime(start.getTime());end.setMonth(end.getMonth()+1);}else{start.setMonth(0,1);start.setFullYear(start.getFullYear()+offset);end.setTime(start.getTime());end.setFullYear(end.getFullYear()+1);}return {start,end};}
  function calendarDay(date){return `${date.getMonth()+1}月${date.getDate()}日`;}
  function periodLabel(range=currentRange()){const {start,end}=periodBounds(range);if(range==='day')return calendarDay(start);if(range==='week'){const last=new Date(end);last.setDate(last.getDate()-1);return `${calendarDay(start)}—${calendarDay(last)}`;}if(range==='month')return `${start.getFullYear()}年${start.getMonth()+1}月`;return `${start.getFullYear()}年`;}
  function periodNavigation(){const range=currentRange(),offset=periodOffset(),back={day:'回今天',week:'回本周',month:'回本月',year:'回今年'}[range];return `<div class="period-navigation"><button class="period-arrow" data-period-step="-1" aria-label="上一${{day:'日',week:'周',month:'月',year:'年'}[range]}">${icon('back')}</button><strong>${e(periodLabel(range))}</strong><span class="period-nav-end">${offset<0?`<button class="period-reset" data-action="period-reset">${back}</button>`:''}<button class="period-arrow" data-period-step="1" aria-label="下一${{day:'日',week:'周',month:'月',year:'年'}[range]}" ${offset===0?'disabled':''}>${icon('right')}</button></span></div>`;}
  function navigate(route){if(!pageNames[route])return;if(state.route==='activity'&&activityDetails.has(route)){const selected=activityDate(),now=new Date(),selectedWeek=new Date(selected),currentWeek=new Date(now);selectedWeek.setDate(selectedWeek.getDate()-((selectedWeek.getDay()+6)%7));currentWeek.setDate(currentWeek.getDate()-((currentWeek.getDay()+6)%7));state.ranges[route]='day';state.periodOffsets[route]={day:state.activityDateOffset,week:Math.round((selectedWeek-currentWeek)/604800000),month:(selected.getFullYear()-now.getFullYear())*12+selected.getMonth()-now.getMonth(),year:selected.getFullYear()-now.getFullYear()};}closeSheet();if(state.route!==route)state.stack.push(state.route);state.route=route;state.demoStatus='normal';location.hash='/'+route;render(true);}
  function goBack(){if(state.route==='sourceSettings'&&!state.stack.length&&new URLSearchParams(location.search).get('from')==='ecg-my'){location.href='ecg/device-management.html';return;}const prev=state.stack.pop()||'home';state.route=prev;state.demoStatus='normal';location.hash='/'+prev;render(true);}
  function header(title){const route=state.route,choice=displaySourceName(selectedSource(route)||'未设置'),aggregate=aggregateRoutes.has(route);return `<header class="page-head"><button class="icon-button" data-action="back" aria-label="返回">${icon('back')}</button><h1>${e(title)}</h1>${activityDetails.has(route)?`<span class="source-switch source-readonly" aria-label="数据来源由活动总览设置">${icon('source')}<span>${e(choice)}</span></span>`:sourceOptions[route]?`<button class="source-switch" data-action="source-menu" aria-label="${aggregate?'查看数据来源':`调整来源排序，当前${e(choice)}`}" aria-haspopup="dialog">${icon('source')}<span>${e(choice)}</span>${icon('right')}</button>`:''}</header>`;}
  function sectionTitle(title,small=''){if(title==='统计摘要')return '';const isRecords=['测量记录','原始记录','相关记录','运动记录','睡眠记录','饮食明细'].includes(title);return `<div class="section-title">${e(isRecords?'全部数据':title)}${small&&!isRecords?`<small>${e(small)}</small>`:''}</div>`;}
  function tabs(items,current,kind,compact=false){return `<div class="segmented${compact?' compact':''}" role="tablist" aria-label="视图切换">${items.map(([key,label])=>`<button type="button" role="tab" aria-selected="${key===current}" class="${key===current?'selected':''}" data-${kind}="${e(key)}">${e(label)}</button>`).join('')}</div>`;}
  function rangeTabs(includeYear=false){return tabs([['day','日'],['week','周'],['month','月'],...(includeYear?[['year','年']]:[])],currentRange(),'range')+periodNavigation();}
  function source(name){return `<span class="source-tag">${icon('source')}${e(displaySourceName(name))}</span>`;}
  function hero({label,value,unit,time,accent='blue'}){const color={blue:'#eaf2ff',pink:'#fff0f4',mint:'#e8faf6',purple:'#f2edff',orange:'#fff2e5'}[accent]||'#eaf2ff';return `<div class="surface metric-hero" style="--accent-soft:${color}"><div class="metric-hero-head"><div class="eyebrow">${e(label)}</div><span class="metric-hero-time">${e(time)}</span></div><div class="metric-number"><strong>${e(value)}</strong><span class="unit">${e(unit)}</span></div></div>`;}
  function stats(items,className=''){return `<div class="stat-grid${className?` ${e(className)}`:''}">${items.map(([label,val,unit])=>`<div class="stat-box"><div class="label">${e(currentRange()==='day'&&label.startsWith('本期')?`当日${label.slice(2)}`:label)}</div><strong>${e(val)} <span>${e(unit||'')}</span></strong></div>`).join('')}</div>`;}
  function fullDate(date){return `${date.getFullYear()}年${date.getMonth()+1}月${date.getDate()}日`;}
  function fullDetailTime(value){const time=String(value||''),now=new Date();if(/^\d{4}年\d{1,2}月/.test(time))return time;const relative=time.match(/^(今天|昨天|前一天|前夜|昨夜|(\d+)天前)(?:\s+|$)/);if(relative){const date=new Date(now.getFullYear(),now.getMonth(),now.getDate()-(relative[2]?Number(relative[2]):relative[1]==='今天'?0:1)),rest=time.slice(relative[0].length).trim();return `${fullDate(date)}${rest?` ${rest}`:''}`;}const {start}=periodBounds(currentRange());const clock=time.match(/^(\d{1,2}):(\d{2})(.*)$/);if(clock)return `${fullDate(start)} ${time}`;if(/^\d{1,2}$/.test(time)){if(currentRange()==='day')return `${fullDate(start)} ${time.padStart(2,'0')}:00`;if(currentRange()==='month')return `${start.getFullYear()}年${start.getMonth()+1}月${Number(time)}日`;}if(currentRange()==='week'){const weekdays=['一','二','三','四','五','六','日'],index=weekdays.indexOf(time);if(index>=0){const date=new Date(start);date.setDate(date.getDate()+index);return fullDate(date);}}if(/^\d{1,2}月$/.test(time))return `${start.getFullYear()}年${time}`;return `${fullDate(start)} ${time}`;}
