  function records(items){const range=currentRange(),filtered=withDemoDays(items).map(r=>({...r,day:recordDay(r.time)})).filter(r=>inCurrentPeriod(r.day,range));if(!filtered.length)return emptyRecords();if(range==='day')return `<div class="record-list">${limitedRows(filtered,recordListKey('day'))}</div>`;const groups=new Map();for(const r of filtered){const key=`${r.day.getFullYear()}-${r.day.getMonth()+1}-${r.day.getDate()}`;if(!groups.has(key))groups.set(key,{day:r.day,items:[]});groups.get(key).items.push(r);}const today=new Date(),todayKey=`${today.getFullYear()}-${today.getMonth()+1}-${today.getDate()}`,all=[...groups.entries()].sort((a,b)=>b[1].day-a[1].day),key=recordListKey('days'),limit=state.recordLimits[key]||7;return `<div class="daily-list">${all.slice(0,limit).map(([dateKey,group])=>{const date=group.day,label=dateKey===todayKey?'今天':`${date.getMonth()+1}月${date.getDate()}日`,groupKey=recordListKey(dateKey);return `<details class="daily-group"${state.expandedRecordGroups.has(groupKey)?' open':''}><summary data-group-key="${e(groupKey)}"><span class="daily-date"><strong>${label}</strong></span><span class="daily-count">${group.items.length} 条数据</span>${icon('right')}</summary><div class="daily-records">${limitedRows(group.items,groupKey)}</div></details>`;}).join('')}${all.length>limit?`<button class="records-more" data-list-more="${e(key)}">查看更多日期</button>`:''}</div>`;}
