  function mockLabels(range){return range==='day'?['00','03','06','09','12','15','18','21']:range==='week'?['一','二','三','四','五','六','日']:range==='month'?['1','4','7','10','13','16','19','22','25','28']:['1月','2月','3月','4月','5月','6月','7月','8月','9月','10月','11月','12月'];}
