  const referenceRanges={heart:{min:60,max:100},oxygen:{min:95,max:100},sleepDuration:{min:7,max:9},bloodPressure:[{min:90,max:119,label:'收缩压'},{min:60,max:79,label:'舒张压'}],hrv:{sdnn:{min:30,max:160},meanrr:{min:600,max:1000},rmssd:{min:15,max:40},pnn50:{min:4.4,max:29}}};
