    const all=kind==='dual'?[...values[0],...values[1]].filter(v=>v!==null):kind==='range'?values.filter(v=>v!==null).flatMap(v=>[v.min,v.max]):values.filter(v=>v!==null);
    const rawMin=opts.min!==undefined?opts.min:Math.min(...all),rawMax=opts.max!==undefined?opts.max:Math.max(...all);
    const extra=(rawMax-rawMin||1)*.16,min=opts.min!==undefined?rawMin:Math.max(0,rawMin-extra),max=opts.max!==undefined?rawMax:rawMax+extra;
    const dayAxis=currentRange()==='day',hourAt=i=>{const explicit=opts.dayHours?.[i];if(Number.isFinite(explicit))return Math.max(0,Math.min(24,explicit));const label=String(opts.pointTimes?.[i]||labels[i]||''),clock=label.match(/(?:^|\D)(\d{1,2}):(\d{2})(?=\D|$)/);if(clock)return Math.max(0,Math.min(24,Number(clock[1])+Number(clock[2])/60));const hour=label.match(/^\d{1,2}$/);if(hour)return Math.max(0,Math.min(24,Number(label)+(kind==='bar'&&labels.length===8?1.5:0)));return (i+.5)*24/Math.max(labels.length,1);};
    const x=i=>dayAxis?l+hourAt(i)/24*plotW:l+(labels.length===1?plotW/2:i*plotW/(labels.length-1));const y=v=>t+plotH-(v-min)/(max-min||1)*plotH;
