  function readyContent(content){return state.demoStatus==='normal'?content:statusPanel();}
  function statusPanel(){const map={unauthorized:['lock','尚未授权读取','请在系统设置中允许读取该指标的数据，授权后即可查看趋势。','重新授权'],noData:['list','暂无记录','当前时间范围内还没有可展示的数据。更换日期或完成一次测量后再查看。','刷新数据'],unsupported:['info','设备暂不支持','当前连接的设备没有产生该指标样本。可查看可用的数据来源。','查看数据来源'],syncFailed:['sync','同步暂时失败','已保留上次同步结果。请检查连接后重试；原有测量时间不会更改。','重试同步']};const [ic,title,desc,cta]=map[state.demoStatus]||map.noData;return `<div class="empty-panel"><div class="empty-icon">${icon(ic)}</div><h2>${title}</h2><p>${desc}</p><button class="primary-button" data-action="reset-state">${cta}</button></div>`;}

