  function topLevelBlocks(html){const blocks=[],tag=/<[^>]+>/g,voidTags=new Set(['area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr']);let depth=0,start=0,match;while((match=tag.exec(html))){const raw=match[0],name=raw.match(/^<\s*(\/?)\s*([A-Za-z][\w:-]*)/);if(!name)continue;const closing=name[1]==='/',selfClosing=/\/\s*>$/.test(raw)||voidTags.has(name[2].toLowerCase());if(closing){depth--;if(depth===0)blocks.push(html.slice(start,tag.lastIndex));}else{if(depth===0)start=match.index;if(!selfClosing)depth++;else if(depth===0)blocks.push(html.slice(start,tag.lastIndex));}}return blocks.length?blocks:[html];}
