  const hrvMetrics={sdnn:{label:'SDNN',unit:'ms',min:0,max:180},meanrr:{label:'MeanRR',unit:'ms',min:500,max:1100},rmssd:{label:'RMSSD',unit:'ms',min:0,max:60},pnn50:{label:'pNN50',unit:'%',min:0,max:40}};
