  function emptyRings(){return `<svg class="rings" viewBox="0 0 112 112" width="128" height="128" role="img" aria-label="活动记录暂无数值">${[49,39,29].map(r=>`<circle cx="56" cy="56" r="${r}" fill="none" stroke="#eef0f5" stroke-width="6"/>`).join('')}</svg>`;}
  function renderActivityHuawei(){const rg=currentRange(),items=[['activeCalories','活动热量','-- / 200 kcal','flame'],['exerciseMinutes','运动分钟','-- / 60 分钟','clock'],['standHours','站立小时','-- / 6 小时','stand'],['steps','步数','-- / 30000 步','steps'],['distance','距离','-- km','flag']];return header('活动总览')+`<div class="surface activity-overview"><div class="top">${emptyRings()}<div class="ring-values"><div><i style="background:${C.pink}"></i><strong>--</strong> / 200 kcal</div><div><i style="background:${C.mint}"></i><strong>--</strong> / 60 分钟</div><div><i style="background:${C.blue}"></i><strong>--</strong> / 6 小时</div></div></div><div class="activity-menu">${items.map(([route,label,value,ic])=>`<button class="activity-link" data-route="${route}"><span>${icon(ic)}</span><small style="display:block;margin-top:4px">${label}</small><strong>${value}</strong></button>`).join('')}</div></div>`+rangeTabs(true)+blankChart(rg==='day'?'今日分时活动热量':'活动热量趋势',{kind:'bar',min:0,max:rg==='day'?32:220,unit:' kcal',color:C.pink})+sectionTitle('运动记录')+emptyRecords();}
  function activityDate(){const now=new Date(),date=new Date(now.getFullYear(),now.getMonth(),now.getDate());date.setDate(date.getDate()+state.activityDateOffset);return date;}
  function activityDateKey(date){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;}
  function activityAge(date){const now=new Date(),today=new Date(now.getFullYear(),now.getMonth(),now.getDate(),12),day=new Date(date.getFullYear(),date.getMonth(),date.getDate(),12);return Math.round((today-day)/86400000);}
  function activityDayData(date){if(selectedSource('activity')!=='苹果健康')return null;const age=activityAge(date),recent=[{calories:115,minutes:28,stand:1,steps:12083,distance:1.6},{calories:104,minutes:22,stand:2,steps:10564,distance:2.3},{calories:132,minutes:37,stand:4,steps:13420,distance:2.1}];if(age<0||age>60)return null;if(age<recent.length)return recent[age];const wave=Math.sin(age*1.71),slow=Math.cos(age*.47),steps=Math.round(10700+wave*2700+slow*1300);return {calories:Math.round(119+wave*32+slow*18),minutes:Math.max(8,Math.round(30+wave*11+slow*7)),stand:Math.max(1,Math.min(6,Math.round(3+wave+slow))),steps,distance:Math.max(.5,Math.round((steps/6900+slow*.3)*10)/10)};}
  function activityRings(size,data){const metrics=[['calories',200,49,C.pink],['minutes',60,39,C.mint],['stand',6,29,C.blue]];return `<svg class="rings" viewBox="0 0 112 112" width="${size}" height="${size}" role="img" aria-label="活动进度">${metrics.map(([key,goal,r,color])=>{const length=2*Math.PI*r,progress=data?Math.min(1,Math.max(0,data[key]/goal)):0;return `<circle cx="56" cy="56" r="${r}" fill="none" stroke="#e9edf4" stroke-width="7"/><circle cx="56" cy="56" r="${r}" fill="none" stroke="${color}" stroke-width="7" stroke-linecap="round" stroke-dasharray="${progress*length} ${length}" transform="rotate(-90 56 56)"/>`;}).join('')}</svg>`;}
  function activityWeekStrip(){const selected=activityDate(),monday=new Date(selected);monday.setDate(monday.getDate()-((monday.getDay()+6)%7));const weekdays=['一','二','三','四','五','六','日'],today=new Date();today.setHours(0,0,0,0);return `<div class="activity-date-controls"><button class="activity-week-arrow" data-activity-week="-1" aria-label="上一周">${icon('back')}</button><button class="activity-date-title" data-action="activity-calendar" aria-label="打开日历选择日期">${fullDate(selected)} 星期${'日一二三四五六'[selected.getDay()]} ${icon('calendar')}</button><button class="activity-week-arrow" data-activity-week="1" aria-label="下一周" ${selected>=today?'disabled':''}>${icon('right')}</button></div><div class="activity-week-strip">${weekdays.map((weekday,i)=>{const date=new Date(monday);date.setDate(date.getDate()+i);const future=date>today,active=activityDateKey(date)===activityDateKey(selected);return `<button class="activity-week-day${active?' active':''}" data-activity-date="${activityDateKey(date)}" aria-label="${fullDate(date)}" ${future?'disabled':''}><span>${weekday}</span><strong>${date.getDate()}</strong>${activityRings(34,activityDayData(date))}</button>`;}).join('')}</div>`;}
  function activityDayCard(){const date=activityDate(),data=activityDayData(date),items=[['activeCalories','flame','活动热量',data?String(data.calories):'--','/ 200 kcal',C.pink],['exerciseMinutes','clock','运动分钟',data?String(data.minutes):'--','/ 60 分钟',C.mint],['standHours','stand','站立小时',data?String(data.stand):'--','/ 6 小时',C.blue],['steps','steps','步数',data?String(data.steps):'--','/ 30000 步',C.blue],['distance','flag','距离',data?data.distance.toFixed(1):'--','km',C.purple]];return `<div class="surface activity-day-card"><div class="activity-day-top">${activityRings(130,data)}</div><div class="activity-metric-list">${items.map(([route,ic,label,value,unit,color])=>`<button class="activity-metric-row" data-route="${route}" aria-label="查看${label}详情"><span class="activity-metric-icon" style="color:${color}">${icon(ic)}</span><span class="activity-metric-name">${label}</span><strong>${value} <small>${unit}</small></strong><span class="activity-metric-chevron">${icon('right')}</span></button>`).join('')}</div></div>`;}
  function activityCalendarMonth(offset){const today=new Date(),first=new Date(today.getFullYear(),today.getMonth()+offset,1),days=new Date(first.getFullYear(),first.getMonth()+1,0).getDate(),leading=first.getDay(),selected=activityDateKey(activityDate()),todayKey=activityDateKey(today);return `<section class="activity-calendar-month"><h3>${first.getFullYear()}年${first.getMonth()+1}月</h3><div class="activity-calendar-grid">${Array.from({length:leading},()=>'<span></span>').join('')}${Array.from({length:days},(_,index)=>{const date=new Date(first.getFullYear(),first.getMonth(),index+1),key=activityDateKey(date),future=key>todayKey;return `<button data-activity-date="${key}" class="activity-calendar-day${key===selected?' selected':''}" aria-label="${fullDate(date)}" ${future?'disabled':''}><span>${index+1}</span>${activityRings(40,activityDayData(date))}</button>`;}).join('')}</div></section>`;}
  function showActivityCalendar(){sheetRoot.innerHTML=`<div class="sheet-overlay" data-action="overlay"><div class="sheet activity-calendar-sheet" role="dialog" aria-modal="true" aria-label="选择时间"><div class="sheet-handle"></div><div class="activity-calendar-head"><h2>选择时间</h2><button data-action="close-sheet" aria-label="关闭">×</button></div><div class="activity-calendar-weekdays">${['日','一','二','三','四','五','六'].map(day=>`<span>${day}</span>`).join('')}</div><div class="activity-calendar-scroll">${Array.from({length:6},(_,index)=>activityCalendarMonth(index-5)).join('')}</div></div></div>`;sheetRoot.querySelector?.('.activity-calendar-head button')?.focus?.();sheetRoot.querySelector?.('.activity-calendar-day.selected')?.scrollIntoView?.({block:'center'});}
  function selectActivityDate(value){const match=String(value).match(/^(\d{4})-(\d{2})-(\d{2})$/);if(!match)return;const date=new Date(Number(match[1]),Number(match[2])-1,Number(match[3])),now=new Date(),today=new Date(now.getFullYear(),now.getMonth(),now.getDate());if(date>today||date.getMonth()!==Number(match[2])-1)return;state.activityDateOffset=activityAge(date)*-1;closeSheet();render(false);}
